"""Exact authorized neutral-hook edits; unrelated Ranger-era files remain frozen."""
import json

ADDITIONS = {'src/main/java/com/w0of26/martialspells/combat/PenanceCritContext.java', 'src/main/java/com/w0of26/martialspells/api/AbilityCompatibility.java', 'src/main/java/com/w0of26/martialspells/mixin/ApothicPenanceCriticalChanceMixin.java', 'src/main/java/com/w0of26/martialspells/events/AbilityCompatibilityCooldownEvents.java'}

REPLACEMENTS = {'src/main/java/com/w0of26/martialspells/entity/BearTrapEntity.java': [('', 'import com.w0of26.martialspells.api.AbilityCompatibility;\nimport com.w0of26.martialspells.spells.BearTrapSpell;\n'), ('', '        // Source modifiers resolve at impact over captured power, including the status health gate.\n        double adjustment = AbilityCompatibility.getBearTrapPowerAdjustment(owner);\n        float basePower = entityData.get(DAMAGE_POWER);\n        float impactPower = basePower * (float) (1.0 + adjustment);\n        float controlLimit = entityData.get(CONTROL_LIMIT)\n                + basePower * BearTrapSpell.CONTROL_POWER_MULTIPLIER * (float) adjustment;\n'), ('                    entityData.get(DAMAGE_POWER)\n', '                    impactPower\n'), ('        if (target.getMaxHealth() <= entityData.get(CONTROL_LIMIT)) {\n', '        if (target.getMaxHealth() <= controlLimit) {\n')], 'src/main/java/com/w0of26/martialspells/entity/PenanceProjectile.java': [('', 'import com.w0of26.martialspells.combat.PenanceCritContext;\nimport net.minecraft.world.damagesource.DamageSource;\n'), ('        boolean damaged =\n                DamageSources.applyDamage(\n                        target,\n                        damage,\n                        MartialSpellRegistry.PENANCE\n                                .get()\n                                .getDamageSource(owner)\n                );\n\n        target.invulnerableTime =\n                previousInvulnerableTime;\n', '        DamageSource source = MartialSpellRegistry.PENANCE.get().getDamageSource(owner);\n        boolean damaged;\n        try (PenanceCritContext.Scope ignored = PenanceCritContext.enter(source, target, owner)) {\n            damaged = DamageSources.applyDamage(target, damage, source);\n        } finally {\n            target.invulnerableTime = previousInvulnerableTime;\n        }\n')], 'src/main/java/com/w0of26/martialspells/spells/DemoralizingShoutSpell.java': [('', 'import com.w0of26.martialspells.api.AbilityCompatibility;\nimport net.minecraft.world.entity.player.Player;\n'), ('', '        if (caster instanceof Player player) {\n            // Source 1 + 4.0 = 5x chip damage. The independent control gate is untouched.\n            directDamage *= (float) (1.0 + AbilityCompatibility.getShoutDamageMultiplierAdjustment(player));\n        }\n')], 'src/main/java/com/w0of26/martialspells/spells/PaladinCircleOfHealingSpell.java': [('', 'import com.w0of26.martialspells.api.AbilityCompatibility;\nimport net.minecraft.world.entity.player.Player;\n'), ('', '        // Apply once to the output coefficient shared by all allies in this cast.\n        float healCoefficient = HEAL_COEFFICIENT;\n        if (caster instanceof Player player) {\n            healCoefficient *= (float) (1.0 + AbilityCompatibility.getCircleOfHealingPowerAdjustment(player));\n        }\n\n'), ('                HEAL_COEFFICIENT\n', '                healCoefficient\n'), ('                    HEAL_COEFFICIENT\n', '                    healCoefficient\n')]}

def normalize_ability_hooks(relative, text):
    for before, after in REPLACEMENTS.get(relative, []):
        if text.count(after) < 1:
            return text
        text = text.replace(after, before, 1)
    if relative == "src/main/resources/martial_spells.mixins.json":
        data = json.loads(text)
        if data["mixins"].count("ApothicPenanceCriticalChanceMixin") != 1:
            return text
        data["mixins"].remove("ApothicPenanceCriticalChanceMixin")
        text = json.dumps(data, indent=2) + "\n"
    return text
